#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    cin >> L >> C;

    vector<string> grid(L);
    pair<int, int> start;
    for (int i = 0; i < L; ++i) {
        cin >> grid[i];
        for (int j = 0; j < C; ++j) {
            if (grid[i][j] == 'o') start = {i, j};
        }
    }

    const int dr[] = {-1, 1, 0, 0};
    const int dc[] = {0, 0, -1, 1};

    int prevR = start.first, prevC = start.second;
    int curR = -1, curC = -1;

    for (int d = 0; d < 4; ++d) {
        int nr = start.first + dr[d];
        int nc = start.second + dc[d];
        if (nr >= 0 && nr < L && nc >= 0 && nc < C && grid[nr][nc] == 'H') {
            curR = nr;
            curC = nc;
            break;
        }
    }

    while (true) {
        int nextR = -1, nextC = -1;
        for (int d = 0; d < 4; ++d) {
            int nr = curR + dr[d];
            int nc = curC + dc[d];
            if (nr >= 0 && nr < L && nc >= 0 && nc < C &&
                grid[nr][nc] == 'H' && !(nr == prevR && nc == prevC)) {
                nextR = nr;
                nextC = nc;
                break;
            }
        }

        if (nextR == -1) break;
        prevR = curR;
        prevC = curC;
        curR = nextR;
        curC = nextC;
    }

    cout << curR + 1 << ' ' << curC + 1 << '\n';
    return 0;
}
